import string

def count_words(text):
    text = text.lower()
    words = text.split()
    counts = {}
    for word in words:
        word = word.translate(str.maketrans('', '', string.punctuation))
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts
```

